// Frame
// ---------------------------------------------------------------------------

// Diagnostic: the engine's screen tint. Lock carries it every frame - FlashScale and
// FlashFog - and EndFlash applies it: damage flashes, the underwater tint and the
// augmentations' colouring all arrive this way. What values actually come, and when, is
// reported here: each distinct pair (to two decimals), the first sixteen of them.
static void NoteFlash(const FPlane& Scale, const FPlane& Fog)
{
    enum { MAX_SEEN = 16 };
    static INT Seen[MAX_SEEN][6];
    static INT SeenCount = 0;
    INT K[6] = { (INT)(Scale.X * 100.0f + 0.5f), (INT)(Scale.Y * 100.0f + 0.5f), (INT)(Scale.Z * 100.0f + 0.5f),
                 (INT)(Fog.X * 100.0f + 0.5f),   (INT)(Fog.Y * 100.0f + 0.5f),   (INT)(Fog.Z * 100.0f + 0.5f) };
    for (INT i = 0; i < SeenCount; i++)
    {
        UBOOL bSame = 1;
        for (INT c = 0; c < 6; c++)
            if (Seen[i][c] != K[c]) bSame = 0;
        if (bSame)
            return;
    }
    if (SeenCount >= MAX_SEEN)
        return;
    for (INT c = 0; c < 6; c++)
        Seen[SeenCount][c] = K[c];
    SeenCount++;
    RDX_LOGF("screen tint: FlashScale (%.2f %.2f %.2f %.2f)  FlashFog (%.2f %.2f %.2f %.2f)",
             Scale.X, Scale.Y, Scale.Z, Scale.W, Fog.X, Fog.Y, Fog.Z, Fog.W);
}

// The meshes' fog is gathered while their triangles come, and laid down in one run when anything else comes - another
// kind of draw, a blended mesh, a new scene node, the depth clear, the frame's end (FlushMeshFog). Drawn with each
// triangle it would split every mesh into two runs a triangle: in the sewers 166 draws would be 1459. Two gatherings:
// the meshes drawn whole, and the masked ones, whose fog goes only where they wrote the depth themselves
// (BLEND_FogEqual) - over their holes it would fog whatever shows through them.
enum { MeshFogRoom = 3 * 4096 };
static FSolidVertex GMeshFog[2][MeshFogRoom];        // [0] the whole ones', [1] the masked ones'
static INT          GMeshFogCount[2] = { 0, 0 };

static void FlushMeshFog(FBackend& Backend)
{
    const INT White = Backend.GetWhiteSrv();
    for (INT k = 0; k < 2; k++)
    {
        if (GMeshFogCount[k] <= 0)
            continue;
        FSolidVertex* const V = (White >= 0) ? Backend.BeginTriangles(GMeshFogCount[k] / 3, White, -1,
                                                                      k ? BLEND_FogEqual : BLEND_Fog, 0)
                                             : nullptr;
        if (V)
            appMemcpy(V, GMeshFog[k], sizeof(FSolidVertex) * GMeshFogCount[k]);
        GMeshFogCount[k] = 0;
    }
}

// A lost device made again, between two frames. A device comes back only once every object of the old one is let go -
// while one lives, asking for a device hands the lost one back - so nothing is mended in place: the whole renderer is
// taken down as at the game's end, the backend is built anew where it stands, and the renderer is brought up as at
// its start. The settings are the file's again: what the menu changed in the running game goes with the device.
// Tried a moment after the loss and a few times more, some seconds apart; a device that does not come back leaves the
// window's title saying so. At once (bAtOnce) where the device itself is whole and only what was made on it is not -
// targets a change of size left unmade (Lock): there is nothing to wait for then, and nothing whole to draw with.
void URevisionRenderDevice::RecoverLostDevice(UBOOL bAtOnce)
{
    enum { TRIES = 5 };
    static INT    Tries  = 0;
    static DOUBLE NextAt = 0.0, LostAt = 0.0;
    static UBOOL  bDeviceWhole = 0;     // what is said on the screen afterwards is said of what happened
    UViewport* const V   = URenderDevice::Viewport;
    const DOUBLE     Now = appSeconds();
    // A measurement only (the marker SecondRevision-lost-exit.txt): the game ends at the loss, with no renderer brought
    // up again. A run that looks for what loses the device then loses it once: where the scene itself loses it, every
    // try below loses it again a moment later, and a driver whose device was lost many times in a row stops answering
    // - the game's process can then not even end. Ended outright, not through the engine: its way out goes through
    // the lost device.
    if (!GDeviceGone && !bAtOnce && FreshMarker(L"SecondRevision-lost-exit.txt"))
    {
        RDX_LOG("lost device: the game ends here, nothing is brought up again (the marker SecondRevision-lost-exit.txt)");
        ::TerminateProcess(::GetCurrentProcess(), 3);
    }
    if (!GDeviceGone)
    {
        GDeviceGone  = 1;
        Tries        = 0;
        LostAt       = Now;
        NextAt       = bAtOnce ? Now : Now + 1.0;
        bDeviceWhole = bAtOnce;
        if (!bAtOnce)
            return;
    }
    if (!V || Tries >= TRIES || Now < NextAt)
        return;
    Tries++;
    NextAt = Now + 5.0;
    const HWND  Window = (HWND)V->GetWindow();
    const INT   X = V->SizeX, Y = V->SizeY, Bytes = V->ColorBytes, Frames = FrameCounter;
    const UBOOL bFull = GEngineFullscreen;
    RDX_LOGF("lost device: the renderer is taken down and brought up again, try %i of %i (%ix%i)", Tries, (INT)TRIES,
             X, Y);
    Exit();
    Backend.~FBackend();
    {
        const FRdxInPlace Here = { &Backend };
        new (Here) FBackend();
    }
    // What Exit leaves of this side's memory of the card: as at a level's change (Flush).
    ForgetShadowLevel();
    ForgetCoronaTextures();
    ForgetFallTextures();
    GLevelFlushes++;
    const UBOOL bUp = Init(V, X, Y, Bytes, bFull) && Backend.IsReady() && !Backend.GetDeviceLost();
    FrameCounter = Frames;
    if (!bUp)
    {
        // Left clean: a backend half up would be drawn with.
        Backend.Shutdown();
        RDX_LOGF("lost device: the renderer did NOT come up (try %i of %i)", Tries, (INT)TRIES);
        if (Tries >= TRIES && Window)
            ::SetWindowTextW(Window, L"Deus Ex - GRAPHICS DEVICE LOST - please restart the game");
        return;
    }
    GDeviceGone = 0;
    if (Window && GWindowTitle[0])
        ::SetWindowTextW(Window, GWindowTitle);
    // Said on the screen: the picture stood for a moment, and whatever the menu had changed is the file's again.
    Backend.ShowNotice(bDeviceWhole ? "A CHANGE OF MODE COULD NOT BE MADE\nTHE RENDERER WAS RESTARTED\n"
                                      "THE SETTINGS FILE APPLIES AGAIN"
                                    : "THE GRAPHICS DEVICE WAS LOST AND RESTARTED\nTHE SETTINGS FILE APPLIES AGAIN",
                       8.0f);
    RDX_LOGF("lost device: the renderer is up again with the file's settings, %.1f s after the loss - the picture "
             "goes on", (FLOAT)(appSeconds() - LostAt));
}

