// RevisionSplashScreenFix: the game's own loading pictures - a picture of the chapter, shown in the one frame the
// engine paints before it loads a level or a saved game. The game draws the picture pixel for pixel, its middle cut
// out to the screen's size, and on a screen taller than the picture it draws a black tile in its place. Two things are
// done about that, in that one frame alone - the level says LEVACT_Loading before the frame is drawn:
//   - the engine's canvas is told a height, and a width, no larger than the picture's, so that the game draws the
//     picture (SplashCanvas). The engine writes the canvas's size again within the frame, so it is told at every call
//     of the frame that comes before the game's own drawing. The engine's resolution is not touched;
//   - the picture is laid in the screen's middle at the size at which its own middle, where its content is, just
//     fits the screen (RdxMath::SplashView), over a black screen: the same content at the same share of every screen,
//     where the game by itself shows more of the backdrop the larger the screen is. What the game draws over the
//     picture after it is moved and sized with it (DrawTile).
// A tile is taken for the picture only where it comes as the game draws one: a large texture, pixel for pixel, cut
// from its middle, at the screen's corner. Anything else a game or a mod draws in that frame is left as it comes.
struct FSplashFrame
{
    UBOOL bPicture;          // this frame's picture was laid: what comes after it is moved with it
    FLOAT FromX, FromY;      // the picture's texel under a point of the game's layout: From + point * Per
    FLOAT PerX, PerY;
    FLOAT ToX, ToY, Scale;   // where the picture's own corner falls on the screen, and the screen's pixels a texel
};
static FSplashFrame GSplash       = { 0, 0.0f, 0.0f, 1.0f, 1.0f, 0.0f, 0.0f, 1.0f };
static UBOOL        GSplashLaying = 0;      // the picture's own tiles are on their way through DrawTile

static UBOOL SplashFrameNow(UViewport* V)
{
    return GRunSplashFix && V && V->Actor && V->Actor->Level && V->Actor->Level->LevelAction == LEVACT_Loading;
}

// LoadFix: a fault of the game's own, worked around. The engine opens a saved game's level package before it lets
// the running level go, and where the two carry one name the save's objects are made over the running level's, name
// by name. Two saves of one place from two playthroughs do not hold the same objects under the same names - the
// player's conversation history least of all - and the game ends in the garbage collection that follows the load.
// With the running level's package under another name the save loads as it does from any other level: nothing is
// made over anything, and the old level goes whole.
//
// A saved game's load alone: what travels with the player from level to level is found again by its objects' names,
// the old level's among them. The game says which it is in its log before it loads ("Doing loadgame, not load") -
// heard through the log's hook, in line with whoever hooked it before - and the engine paints one frame before it
// opens the save's package, with the level saying LEVACT_Loading: at that frame's end the package is renamed. It
// is the first frame after the game's word or none: a load that failed before it leaves nothing waiting.
static UBOOL GLoadGameSaid = 0;
class FLoadGameEar : public FOutputDevice
{
public:
    FOutputDevice* Before = nullptr;
    UBOOL          bIn    = 0;
    void Serialize(const TCHAR* V, EName Event)
    {
        if (Before)
            Before->Serialize(V, Event);
        if (bIn && V && appStrstr(V, TEXT("Doing loadgame")))
            GLoadGameSaid = 1;
    }
};
static FLoadGameEar GLoadGameEar;

static void LoadFixListen(UBOOL bOn)
{
    if (bOn && !GLoadGameEar.bIn)
    {
        // Not twice in the line: taken out below only while it is the last one in.
        if (GLogHook != &GLoadGameEar)
        {
            GLoadGameEar.Before = GLogHook;
            GLogHook            = &GLoadGameEar;
        }
        GLoadGameEar.bIn = 1;
    }
    else if (!bOn && GLoadGameEar.bIn)
    {
        GLoadGameEar.bIn = 0;
        GLoadGameSaid    = 0;
        // Somebody who hooked the log after this one hands it on through here: then it stays, and only hands on.
        if (GLogHook == &GLoadGameEar)
        {
            GLogHook            = GLoadGameEar.Before;
            GLoadGameEar.Before = nullptr;
        }
    }
}

static void LoadFixFrame(UViewport* V)
{
    if (!GLoadGameSaid)
        return;
    GLoadGameSaid = 0;
    if (!GRunLoadFix || !V || !V->Actor || !V->Actor->Level || V->Actor->Level->LevelAction != LEVACT_Loading)
        return;
    ULevel* const  Level   = V->Actor->GetLevel();
    UObject* const Package = Level ? Level->GetOuter() : nullptr;
    // The entry level is the engine's to keep, under its own name.
    if (!Package || Package->GetOuter() || !appStricmp(Package->GetName(), TEXT("Entry")))
        return;
    const FString Was = Package->GetName();
    Package->Rename();
    RDX_LOGF("load fix: a saved game is loading - the running level's package %s is %s from here on, and the save's "
             "level loads beside it, not over it", *Was, Package->GetName());
}

static void SplashCanvas(UViewport* V)
{
    if (!SplashFrameNow(V) || !V->Canvas)
        return;
    UCanvas* const C = V->Canvas;
    if (C->ClipX > RdxMath::SplashMaxWidth)
        C->ClipX = RdxMath::SplashMaxWidth;
    if (C->ClipY > RdxMath::SplashMaxHeight)
        C->ClipY = RdxMath::SplashMaxHeight;
    if (C->X > (INT)RdxMath::SplashMaxWidth)
        C->X = (INT)RdxMath::SplashMaxWidth;
    if (C->Y > (INT)RdxMath::SplashMaxHeight)
        C->Y = (INT)RdxMath::SplashMaxHeight;
}

void URevisionRenderDevice::Lock(FPlane FlashScale, FPlane FlashFog, FPlane ScreenClear,
                                 DWORD /*RenderLockFlags*/, BYTE* /*HitData*/, INT* /*HitSize*/)
{
    // The engine has done the frame's simulation and starts drawing it (FBackend::FrameDrawStarts).
    Backend.FrameDrawStarts();
    if (GLatencyProbe)
    {
        LARGE_INTEGER Q;
        ::QueryPerformanceCounter(&Q);
        GLatencyStart = Q.QuadPart;
        const APlayerPawn* const P = URenderDevice::Viewport ? URenderDevice::Viewport->Actor : nullptr;
        GLatencyPitch = P ? P->ViewRotation.Pitch : 0;
        GLatencyYaw   = P ? P->ViewRotation.Yaw : 0;
    }
    // Before anything of the frame: a device that was lost, or one that did not come back at the last try.
    if (Backend.GetDeviceLost() || GDeviceGone)
        RecoverLostDevice();
    GSplash.bPicture = 0;
    SplashCanvas(URenderDevice::Viewport);
    ResetNodeStats();
    GMeshFogCount[0] = 0;       // a frame's fog is its own
    GMeshFogCount[1] = 0;
    RdxWaterFrameStart();
    GHud.bSwitched = GHud.bClearAfter = GHud.bLate = 0;
#if RDX_DIAG_DRAW_ORDER
    {
        // The 120th frame is still in the menus; after a level change, frames 30, 300, 600, 900,
        // 1200 and 1500 - which also covers a menu opened over the game (scene.ps1 -CursorProbe).
        const INT SinceLoad = FrameCounter - GSorLoadFrame;
        GSorActive = (FrameCounter == 120) || SinceLoad == 30 ||
                     (SinceLoad >= 300 && SinceLoad <= 1500 && (SinceLoad % 300) == 0);
        GSorLen = 0; GSorBuf[0] = 0; GSorLast = 0; GSorRun = 0;
        GSorRootZ = 0;
        appMemzero(GSorZHist, sizeof(GSorZHist));
    }
#endif
    NoteFlash(FlashScale, FlashFog);
    LastFlashScale = FlashScale;
    LastFlashFog   = FlashFog;

    // What the engine actually holds for our capability flags once its config has been
    // applied - the constructor's values are only a starting point for a config class.
    // Reason to look: whether the engine agrees that we take coronas. It does, and they arrive - as tiles at
    // Z = 1, the engine having projected and cropped them itself (see the corona note in DrawTile).
    static UBOOL bFlagsReported = 0;
    if (!bFlagsReported)
    {
        bFlagsReported = 1;
        RDX_LOGF("capabilities: Coronas %i, VolumetricLighting %i, ShinySurfaces %i, HighDetailActors %i, "
                 "DetailTextures %i, SupportsTC %i, SupportsFogMaps %i, SupportsDistanceFog %i",
                 (INT)URenderDevice::Coronas, (INT)URenderDevice::VolumetricLighting,
                 (INT)URenderDevice::ShinySurfaces, (INT)URenderDevice::HighDetailActors,
                 (INT)URenderDevice::DetailTextures, (INT)URenderDevice::SupportsTC,
                 (INT)URenderDevice::SupportsFogMaps, (INT)URenderDevice::SupportsDistanceFog);
    }
    {
        const DOUBLE Now = appSeconds();
        if (GTime.PrevEnd > 0.0)
            GTime.SumOutside += Now - GTime.PrevEnd;
        GTime.LockAt = Now;
        GTime.Draw   = 0.0;
        appMemzero(GTime.Kind, sizeof(GTime.Kind));
        appMemzero(GTime.Calls, sizeof(GTime.Calls));
        GTime.LockOwn = 0.0;
    }

    if (!Backend.IsReady())
        return;

    // The way the plants grow changed (the menu): their mesh goes before anything of the frame is drawn, and they grow
    // again into a new one (TreesReady) - TreeMeshBuffer makes none while the old one is there.
    if (GTreesRegrow)
        Backend.DropTreeMesh();

    // The engine tells us the frame size through the scene node, but Lock comes first.
    // If the window changed underneath us, catch it here rather than rendering to a
    // stale swap chain for a frame.
    if (URenderDevice::Viewport &&
        (URenderDevice::Viewport->SizeX != Backend.GetWidth() ||
         URenderDevice::Viewport->SizeY != Backend.GetHeight()))
    {
        Backend.Resize(URenderDevice::Viewport->SizeX, URenderDevice::Viewport->SizeY);
    }

    // Targets that a change of size or mode left unmade - here just above, or in the menu's changes after the frame
    // before - with the ones before them not put back either: a frame begun now would draw into what is not there.
    // The renderer is taken down and brought up again on the spot, as after a lost device; where it does not come up,
    // no frame is begun, and it is tried again as a lost device is.
    if (Backend.TargetsUnmade() && !GDeviceGone)
    {
        RDX_LOG("resize: the targets were left unmade - the renderer is taken down and brought up again");
        RecoverLostDevice(1);
        if (!Backend.IsReady())
            return;
    }

    // The screen's variable refresh, when the driver's answer comes (AskVrr).
    {
        INT Vrr;
        if (RdxTakeVrr(Vrr))
            Backend.SetVrrState(Vrr);
    }

    // A conversation's camera and its speaker, for the depth of field - before the frame is drawn, so the focus is this
    // frame's.
    {
        FLOAT At[3];
        const UBOOL bTalk = ConversationFocus(URenderDevice::Viewport, FrameCounter, At);
        Backend.SetConversationFocus(bTalk, At);
    }

    // The game's Brightness setting, read every frame so the slider works mid-game.
    if (URenderDevice::Viewport && URenderDevice::Viewport->GetOuterUClient())
        Backend.SetBrightness(URenderDevice::Viewport->GetOuterUClient()->Brightness);

    // The view's field of view (FovAngle is horizontal) - the G-buffer's diagnostic normal view needs it.
    if (URenderDevice::Viewport && URenderDevice::Viewport->Actor)
    {
        const FLOAT TanX = (FLOAT)appTan(URenderDevice::Viewport->Actor->FovAngle * PI / 360.0);
        const INT   SX   = (URenderDevice::Viewport->SizeX > 0) ? URenderDevice::Viewport->SizeX : 1;
        Backend.SetViewTangents(TanX, TanX * (FLOAT)URenderDevice::Viewport->SizeY / (FLOAT)SX);
    }

#if RDX_BRINGUP_CLEAR
    // TEMPORARY, bring-up only. The engine's measured ScreenClear is (0,0,0,0), which
    // is indistinguishable from "the renderer did nothing" on a black window. A
    // deliberate colour proves that the swap chain really is being presented.
    // Remove once anything real is drawn.
    FPlane Bringup;
    Bringup.X = 0.10f; Bringup.Y = 0.18f; Bringup.Z = 0.42f; Bringup.W = 1.0f;
    Backend.BeginFrame(Bringup);
#else
    Backend.BeginFrame(ScreenClear);
#endif
    // FlashlightBeam: the game's own flashlight put out for the frame, the cone in its place (PutOutGameBeams).
    PutOutGameBeams(Backend, URenderDevice::Viewport, FrameCounter);
    // HdtpHoloFix: the level's holograms found, those with an HDTP model dressed for the frame (DressHolograms). A
    // measurement's marker lays their nearest surface as another number of layers, said in hundredths.
    static const INT HoloLayers = MarkerNumber(L"SecondRevision-holo-layers.txt", 0, 0);
    if (HoloLayers > 0)
        Backend.SetHoloShellLayers((FLOAT)HoloLayers * 0.01f);
    DressHolograms(URenderDevice::Viewport);
    // Trees3D: the level's plants hidden from the engine for the world's view and its mirrors (HideLevelTrees).
    HideLevelTrees(Backend, URenderDevice::Viewport, FrameCounter);
    // A measurement only (the marker SecondRevision-water-shadow-off.txt, looked at every thirtieth frame): the
    // see-through water takes the shadow of what lies under it, as before it had its own - the frame time's A/B within
    // one start.
    {
        static INT   WaterMarkFrame = -1000;
        static UBOOL bWaterMarkOff  = 0;
        if (FrameCounter - WaterMarkFrame >= 30 || FrameCounter < WaterMarkFrame)
        {
            WaterMarkFrame    = FrameCounter;
            const UBOOL bOff  = FreshMarker(L"SecondRevision-water-shadow-off.txt");
            if (bOff != bWaterMarkOff)
                RDX_LOGF("water shadow: %s by the measurement marker, at frame %i",
                         bOff ? TEXT("left out") : TEXT("back"), FrameCounter);
            bWaterMarkOff = bOff;
            Backend.SetWaterShadowMarkOff(bOff);
        }
    }
    GTime.LockOwn = appSeconds() - GTime.LockAt;
}

